    Bug 1934979 - Support protocols that don't use nsIMsgMailnewsUrl, such as EWS, when composing from a draft. r=#thunderbird-back-end-reviewers


    It turns out it doesn't matter if the URL is an `nsIMsgMailnewsUrl` when the
    protocol we're getting the message from doesn't necessarily expect it to be. EWS
    doesn't use `nsIMsgMailnewsUrl`-based URLs, and doesn't expect its URLs to
    implement it.

    This patch also implements `nsIMsgMessageService::StreamMessage` using the util
    method added in https://phabricator.services.mozilla.com/D228378.

    Differential Revision: https://phabricator.services.mozilla.com/D231284

diff --git a/mailnews/compose/src/nsMsgComposeService.cpp b/mailnews/compose/src/nsMsgComposeService.cpp
index 30789d96946..514a24f5831 100644
--- a/mailnews/compose/src/nsMsgComposeService.cpp
+++ b/mailnews/compose/src/nsMsgComposeService.cpp
@@ -1198,16 +1198,12 @@ nsresult nsMsgComposeService::RunMessageThroughMimeDraft(
   NS_ENSURE_SUCCESS(rv, rv);

   nsCOMPtr<nsIMsgMailNewsUrl> mailnewsurl = do_QueryInterface(url);
-  if (!mailnewsurl) {
-    NS_WARNING(
-        "Trying to run a message through MIME which doesn't have a "
-        "nsIMsgMailNewsUrl?");
-    return NS_ERROR_UNEXPECTED;
+  if (mailnewsurl) {
+    // If the current protocol uses `nsIMsgMailNewsUrl`, call `SetSpecInternal`
+    // so the base URL is parsed as the message service will expect.
+    rv = mailnewsurl->SetSpecInternal(mailboxUri);
+    NS_ENSURE_SUCCESS(rv, rv);
   }
-  // SetSpecInternal must not fail, or else the URL won't have a base URL and
-  // we'll crash later.
-  rv = mailnewsurl->SetSpecInternal(mailboxUri);
-  NS_ENSURE_SUCCESS(rv, rv);

   // if we are forwarding a message and that message used a charset override
   // then forward that as auto-detect flag, too.
diff --git a/mailnews/protocols/ews/src/EwsService.cpp b/mailnews/protocols/ews/src/EwsService.cpp
index fc7c0cac882..36e2f052d82 100644
--- a/mailnews/protocols/ews/src/EwsService.cpp
+++ b/mailnews/protocols/ews/src/EwsService.cpp
@@ -238,8 +238,9 @@ NS_IMETHODIMP EwsService::StreamMessage(
     const nsACString& aMessageURI, nsIStreamListener* aStreamListener,
     nsIMsgWindow* aMsgWindow, nsIUrlListener* aUrlListener, bool aConvertData,
     const nsACString& aAdditionalHeader, bool aLocalOnly, nsIURI** _retval) {
-  NS_WARNING("StreamMessage");
-  return NS_ERROR_NOT_IMPLEMENTED;
+  // TODO: Convert the message content when `aConvertData = true`. It's usually
+  // not the case, except when we're deleting an attachment.
+  return GetMessageContent(aMessageURI, nullptr, aStreamListener);
 }

 NS_IMETHODIMP EwsService::StreamHeaders(const nsACString& aMessageURI,
